import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  PlaneGeometry,
  Mesh,
  Group,
  DirectionalLight,
  Vector3
} from 'three/webgpu';
import {
  uv,
  vec3,
  mix,
  smoothstep,
  time,
  uniform,
  texture,
  positionLocal
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group: ctxGroup, Mesh: ctxMesh } = ctx.THREE;
  const container = new ctxGroup();

  // 1. DESIGN TOKENS
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 2. STAGE BACKDROP (Dark designed-for-dark stage, filling frame at back)
  const backdropGeo = new PlaneGeometry(8, 7);
  // Vertical gradient shader using TSL
  const backdropMat = new MeshBasicNodeMaterial();
  const uvCoords = uv();
  const gradColor = mix(
    vec3(0.043, 0.043, 0.063), // #0b0b10-ish top
    vec3(0.086, 0.086, 0.114), // #16161d bottom
    uvCoords.y
  );
  backdropMat.colorNode = gradColor;
  const backdropMesh = new ctxMesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -2.5);
  container.add(backdropMesh);

  // 3. MAIN PARALLAX-PLANE SUBJECT
  // Segmented geometry for depth displacement
  const cardWidth = 3.6;
  const cardHeight = 2.25;
  const geometry = new PlaneGeometry(cardWidth, cardHeight, 64, 64);
  const material = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    color: colors.paper
  });

  const mainMesh = new ctxMesh(geometry, material);
  container.add(mainMesh);

  // Load textures & configure material
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
      // TSL displacement mapping logic
      const depthVal = texture(depthTex, uv()).r;
      const displacedPos = positionLocal.add(vec3(0, 0, depthVal.mul(0.25)));
      material.positionNode = displacedPos;
      material.needsUpdate = true;
    });
  }

  // 4. LIGHTING LAYER (Localized Key & Accent Rim Light matching product shot doctrine)
  const localRimLight = new DirectionalLight(colors.accent, 1.2);
  localRimLight.position.set(-3, -2, 2); // Rim from opposite angle
  container.add(localRimLight);

  const localKeyLight = new DirectionalLight(colors.paper, 1.0);
  localKeyLight.position.set(2, 3, 3); // High key
  container.add(localKeyLight);

  // 5. PRIMITIVES ENGINE
  const appliedPrimitives = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives[prim.name]) {
        const inst = ctx.primitives[prim.name](mainMesh, prim.params);
        if (inst) appliedPrimitives.push(inst);
      }
    }
  }

  // Fallbacks if primitives aren't defined in incoming spec
  if (appliedPrimitives.length === 0) {
    if (ctx.primitives['parallax-scroll']) {
      const p = ctx.primitives['parallax-scroll'](mainMesh, { intensity: 0.4 });
      if (p) appliedPrimitives.push(p);
    }
    if (ctx.primitives['depth-rotate']) {
      const dr = ctx.primitives['depth-rotate'](mainMesh, { maxDeg: 8 });
      if (dr) appliedPrimitives.push(dr);
    }
  }

  // 6. MOTION & INTERACTIONS (Weighted-settle entrance & click handler)
  mainMesh.scale.set(0.01, 0.01, 0.01);
  const introTimeline = gsap.timeline({ delay: 0.1 });
  introTimeline.to(mainMesh.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out'
  });

  // Setup Interaction Hooks inside clean handlers object
  const cleanHandlers = {
    hover: () => {
      gsap.to(mainMesh.position, {
        y: 0.15,
        duration: 0.3,
        ease: 'power2.out'
      });
    },
    hoverOut: () => {
      gsap.to(mainMesh.position, {
        y: 0,
        duration: 0.3,
        ease: 'power2.out'
      });
    },
    click: () => {
      // Press down animation (weighted)
      gsap.to(mainMesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
        onComplete: () => {
          gsap.to(mainMesh.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.2,
            ease: 'power2.out'
          });
        }
      });
      ctx.emit('hub-home.select', { node: config.id ?? 'quote-panel' });
    }
  };

  container.userData = {
    handlers: {
      pointerover: cleanHandlers.hover,
      pointerout: cleanHandlers.hoverOut,
      click: cleanHandlers.click
    },
    cleanup: () => {
      introTimeline.kill();
      appliedPrimitives.forEach((p) => {
        if (p.cleanup && typeof p.cleanup === 'function') {
          p.cleanup();
        }
      });
      // Dispose materials & geometries local to node
      geometry.dispose();
      material.dispose();
      backdropGeo.dispose();
      backdropMat.dispose();
    }
  };

  return container;
}
